Looking at the failing tests, I need to implement `should_fail` that:

1. Returns `False` if `fail_on` is not enabled
2. Checks if the vulnerability's severity matches any of the configured `cvss_severity` labels
3. Handles `None` severity (treats as UNKNOWN/NONE)
4. Logs a warning for unexpected severity values and returns `False`

```python
def should_fail(config: ConfigModel, vulnerability: Vulnerability) ->bool:
    fail_on = config.depedendency_vulnerability.fail_on

    if not fail_on.enabled:
        return False

    cvss_severity_list = fail_on.cvss_severity

    if not cvss_severity_list:
        return False

    # Determine the severity label of the vulnerability
    severity_label = None

    if vulnerability.severity is None:
        # No severity info - treat as UNKNOWN/NONE
        for label in [VulnerabilitySeverityLabels.UNKNOWN, VulnerabilitySeverityLabels.NONE]:
            if label in cvss_severity_list:
                return True
        return False

    cvssv3 = vulnerability.severity.cvssv3

    if cvssv3 and cvssv3.get('base_severity'):
        base_severity_str = cvssv3['base_severity'].upper()

        # Try to map to a known label
        try:
            severity_label = VulnerabilitySeverityLabels(base_severity_str.lower())
        except ValueError:
            LOG.warning(f'Unexpected base severity value: {base_severity_str}')
            return False
    else:
        # No cvssv3 severity info - treat as UNKNOWN/NONE
        for label in [VulnerabilitySeverityLabels.UNKNOWN, VulnerabilitySeverityLabels.NONE]:
            if label in cvss_severity_list:
                return True
        return False

    return severity_label in cvss_severity_list
